mapper.select:
/*selectMasterWmPgPrewarhsngReleaseRegList_Check_Yn*/

		SELECT
		    DECODE(COUNT(*), 0, 'Y', 'N') AS CHECK_YN
		FROM
		    KEP_BEFORE_STOCKED_IVDT /* 선입고송장상세 */
		WHERE 1=1
		AND INV_NO = #{INV_NO}
		AND INV_SEQ = #{INV_SEQ}
		AND BUYER = #{BUYER_CODE}
		AND BS_NO = #{BS_NO}
		AND STATUS <> 'D'
		AND WMS_IVK_QTY <> 0 /* 출고가 진행된 경우 */
